1	//! Exposes heap bounds checks functionality for WebAssembly.
2	//! Bounds checks in WebAssembly are critical for safety, so extreme caution is
3	//! recommended when working on this area of Winch.
4	use super::env::HeapData;
5	use crate::{
6	    Result,
7	    abi::vmctx,
8	    codegen::{CodeGenContext, Emission},
9	    isa::reg::{Reg, writable},
10	    masm::{IntCmpKind, IntScratch, MacroAssembler, OperandSize, RegImm, TrapCode},
11	    stack::TypedReg,
12	};
13	
14	/// A newtype to represent an immediate offset argument for a heap access.
15	#[derive(Debug, Copy, Clone)]
16	pub(crate) struct ImmOffset(u32);
17	
18	impl ImmOffset {
19	    /// Construct an [ImmOffset] from a u32.
20	    pub fn from_u32(raw: u32) -> Self {
21	        Self(raw)
22	    }
23	
24	    /// Return the underlying u32 value.
25	    pub fn as_u32(&self) -> u32 {
26	        self.0
27	    }
28	}
29	
30	/// An enum to represent the heap bounds.
31	#[derive(Debug, Copy, Clone)]
32	pub(crate) enum Bounds {
33	    /// Static, known ahead-of-time.
34	    Static(u64),
35	    /// Dynamic. Loaded at runtime.
36	    Dynamic(TypedReg),
37	}
38	
39	impl Bounds {
40	    /// Construct a [Bounds] from a [TypedReg].
41	    pub fn from_typed_reg(tr: TypedReg) -> Self {
42	        Self::Dynamic(tr)
43	    }
44	
45	    /// Construct a [Bounds] from a u64.
46	    pub fn from_u64(raw: u64) -> Self {
47	        Self::Static(raw)
48	    }
49	
50	    /// Return the underlying [TypedReg] value.
51	    pub fn as_typed_reg(&self) -> TypedReg {
52	        match self {
53	            Self::Dynamic(tr) => *tr,
54	            _ => panic!(),
55	        }
56	    }
57	
58	    /// Return the underlying u64 value.
59	    pub fn as_u64(&self) -> u64 {
60	        match self {
61	            Self::Static(v) => *v,
62	            _ => panic!(),
63	        }
64	    }
65	}
66	
67	/// A newtype to represent a heap access index via a [TypedReg].
68	#[derive(Debug, Copy, Clone)]
69	pub(crate) struct Index(TypedReg);
70	
71	impl Index {
72	    /// Construct an [Index] from a [TypedReg].
73	    pub fn from_typed_reg(tr: TypedReg) -> Self {
74	        Self(tr)
75	    }
76	
77	    /// Return the underlying
78	    pub fn as_typed_reg(&self) -> TypedReg {
79	        self.0
80	    }
81	}
82	
83	/// Loads the bounds of the dynamic heap.
84	pub(crate) fn load_dynamic_heap_bounds<M>(
85	    context: &mut CodeGenContext<Emission>,
86	    masm: &mut M,
87	    heap: &HeapData,
88	    ptr_size: OperandSize,
89	) -> Result<Bounds>
90	where
91	    M: MacroAssembler,
92	{
93	    let dst = context.any_gpr(masm)?;
94	    match heap.memory.static_heap_size() {
95	        // Constant size, no need to perform a load.
96	        Some(size) => masm.mov(writable!(dst), RegImm::i64(size.cast_signed()), ptr_size)?,
97	
98	        None => {
99	            masm.with_scratch::<IntScratch, _>(|masm, scratch| {
100	                let base = if let Some(offset) = heap.import_from {
101	                    let addr = masm.address_at_vmctx(offset)?;
102	                    masm.load_ptr(addr, scratch.writable())?;
103	                    scratch.inner()
104	                } else {
105	                    vmctx!(M)
106	                };
107	                let addr = masm.address_at_reg(base, heap.current_length_offset)?;
108	                masm.load_ptr(addr, writable!(dst))
109	            })?;
110	        }
111	    }
112	
113	    Ok(Bounds::from_typed_reg(TypedReg::new(
114	        heap.index_type(),
115	        dst,
116	    )))
117	}
118	
119	/// This function ensures the following:
120	/// * The immediate offset and memory access size fit in a single u64. Given:
121	///   that the memory access size is a `u8`, we must guarantee that the immediate
122	///   offset will fit in a `u32`, making the result of their addition fit in a u64
123	///   and overflow safe.
124	/// * Adjust the base index to account for the immediate offset via an unsigned
125	///   addition and check for overflow in case the previous condition is not met.
126	#[inline]
127	pub(crate) fn ensure_index_and_offset<M: MacroAssembler>(
128	    masm: &mut M,
129	    index: Index,
130	    offset: u64,
131	    heap_ty_size: OperandSize,
132	) -> Result<ImmOffset> {
133	    match u32::try_from(offset) {
134	        // If the immediate offset fits in a u32, then we simply return.
135	        Ok(offs) => Ok(ImmOffset::from_u32(offs)),
136	        // Else we adjust the index to be index = index + offset, including an
137	        // overflow check, and return 0 as the offset.
138	        Err(_) => {
139	            masm.checked_uadd(
140	                writable!(index.as_typed_reg().into()),
141	                index.as_typed_reg().into(),
142	                RegImm::i64(offset as i64),
143	                heap_ty_size,
144	                TrapCode::HEAP_OUT_OF_BOUNDS,
145	            )?;
146	
147	            Ok(ImmOffset::from_u32(0))
148	        }
149	    }
150	}
